// EDIT ME: add/remove RSS feeds you want polled.
// Verify each URL still serves RSS before relying on it -- job boards change this over time.
// LinkedIn/Naukri/Indeed no longer expose public RSS; use the email-alert branch or a job-search
// API (JSearch on RapidAPI, Adzuna API) to cover those instead.
const feeds = [
  { url: 'https://weworkremotely.com/remote-jobs.rss', source: 'WeWorkRemotely' },
  { url: 'https://weworkremotely.com/categories/remote-programming-jobs.rss', source: 'WeWorkRemotely-Programming' },
  { url: 'https://remoteok.com/remote-dev-jobs.rss', source: 'RemoteOK' }
];
return feeds.map(f => ({ json: f }));

return items.map(item => {
  const j = item.json;
  let host = '';
  try { host = new URL(j.link).hostname.replace('www.', ''); } catch (e) {}
  return {
    json: {
      title: j.title || '',
      company: '',
      location: '',
      url: j.link || j.guid || '',
      description: j.contentSnippet || j.content || '',
      source: host || 'RSS',
      postedDate: j.pubDate || j.isoDate || ''
    }
  };
});

// EDIT ME: one entry per company careers page you want watched.
// Inspect the page's HTML (DevTools) to find real selectors -- these are placeholders.
// titleSelector/linkSelector/locationSelector should each match ALL job cards on the page
// so the resulting arrays line up positionally (same order, same count).
const pages = [
  {
    company: 'Example Corp',
    url: 'https://example.com/careers',
    titleSelector: '.job-listing .job-title',
    linkSelector: '.job-listing a',
    locationSelector: '.job-listing .job-location'
  }
];
return pages.map(p => ({ json: p }));

const out = [];
for (const item of items) {
  const j = item.json;
  const titles = j.titles || [];
  const links = j.links || [];
  const locations = j.locations || [];
  for (let i = 0; i < titles.length; i++) {
    out.push({
      json: {
        title: titles[i] || '',
        company: j.company || '',
        location: locations[i] || '',
        url: links[i] || '',
        description: '',
        source: j.company || 'CareerPage',
        postedDate: ''
      }
    });
  }
}
return out;

// Lightweight parser for job-alert emails (LinkedIn/Indeed/Naukri digest style).
// Tune the regexes below to match the actual emails you receive.
const out = [];
for (const item of items) {
  const j = item.json;
  const from = (j.from || (j.headers && j.headers.from) || '').toLowerCase();
  const subject = j.subject || '';
  const isJobAlert = /linkedin|indeed|naukri|job alert|jobs? for you/i.test(from + ' ' + subject);
  if (!isJobAlert) continue;
  const body = j.textPlain || j.text || j.html || '';
  const linkRegex = /(https?:\/\/[^\s"<>]+)/g;
  const links = [...new Set(body.match(linkRegex) || [])].filter(l => /job|career|jd\//i.test(l));
  for (const link of links) {
    out.push({ json: { title: subject, company: '', location: '', url: link, description: '', source: 'EmailAlert', postedDate: j.date || '' } });
  }
}
return out;

// EDIT ME to match what you're looking for. This cheap pass runs BEFORE the paid/rate-limited
// AI call, so keep it loose enough not to miss things but tight enough to save AI credits.
const mustMatchAny = ['python', 'java', 'react', 'node', 'sql', 'data analyst', 'machine learning', 'intern', 'internship', 'software engineer'];
const excludeIfAny = ['senior', 'staff', '10+ years', 'unpaid'];
const preferredLocations = ['remote', 'bangalore', 'chennai', 'hyderabad', 'india'];

return items.filter(item => {
  const text = `${item.json.title} ${item.json.description}`.toLowerCase();
  const loc = (item.json.location || '').toLowerCase();
  const hasMatch = mustMatchAny.some(k => text.includes(k));
  const hasExclude = excludeIfAny.some(k => text.includes(k));
  const locOk = preferredLocations.length === 0 || loc === '' || preferredLocations.some(l => loc.includes(l));
  return hasMatch && !hasExclude && locOk;
});

