return items.map((item, i) => {
  const job = $items('Keyword/Skill Pre-Filter')[i].json;
  let score = 0, matched = [], missing = [], reasoning = '';
  try {
    const content = item.json.choices[0].message.content;
    const parsed = JSON.parse(content);
    score = parsed.match_score || 0;
    matched = parsed.matched_skills || [];
    missing = parsed.missing_skills || [];
    reasoning = parsed.reasoning || '';
  } catch (e) {
    reasoning = 'AI parse failed: ' + e.message;
  }
  return { json: { ...job, match_score: score, matched_skills: matched, missing_skills: missing, reasoning } };
});
